mapper.select:
select fund_id, policy_id, stat_month, enterprise_id, enterprise_name, region_code, accrued_amount,
       used_amount, remaining_amount, fund_status, usage_purpose, evidence_url, last_settle_time,
       source_mode, create_by, create_time, update_by, update_time, remark
from t_prevention_fund

    del_flag = '0'

        and stat_month = #{statMonth}


        and enterprise_id = #{enterpriseId}


        and enterprise_name like concat('%', #{enterpriseName}, '%')


        and fund_status = #{fundStatus}


        and region_code like concat(#{regionCode}, '%')

    ${params.regionDataScope}

order by stat_month desc, fund_status asc, fund_id desc

mapper.insert:
insert into t_prevention_fund (
    policy_id, stat_month, enterprise_id, enterprise_name, region_code, accrued_amount, used_amount,
    remaining_amount, fund_status, usage_purpose, evidence_url, last_settle_time, source_mode,
    del_flag, create_by, create_time, update_by, update_time, remark
) values (
    #{policyId}, #{statMonth}, #{enterpriseId}, #{enterpriseName}, #{regionCode}, #{accruedAmount},
    #{usedAmount}, #{remainingAmount}, #{fundStatus}, #{usagePurpose}, #{evidenceUrl}, #{lastSettleTime},
    #{sourceMode}, '0', #{createBy}, sysdate(), #{updateBy}, sysdate(), #{remark}
)
